# ---------------------------------------------------------------------------
# La base caida es un fallo TEMPORAL: 503 + Retry-After, nunca 500.
#
# Un 500 le dice al rastreador que el fallo es nuestro y sin plazo, y a un
# cliente que reintentar no sirve. Cuando Neon agoto la cuota de computo, la
# home devolvio `500 Internal Server Error` en texto plano durante horas.
# ---------------------------------------------------------------------------
_DB_DOWN_DETAIL = (
    "La base de datos no esta aceptando conexiones. Es temporal; "
    "volve a intentar en unos minutos."
)
_RETRY_AFTER = "300"

# Solo la familia de CONECTIVIDAD. Un `ArgumentError` (cadena de conexion mal
# formada) es un error de configuracion nuestro: reintentar no lo arregla, asi
# que tiene que seguir saliendo 500 y no esconderse detras de un 503.
#
# MEDIDO, no supuesto: con SQLAlchemy+asyncpg un fallo al ABRIR el socket sube
# como `ConnectionRefusedError` PELADO (un OSError), no como excepcion de
# SQLAlchemy — capturar solo las de SQLAlchemy deja pasar el caso mas comun.
# Y el fallo real de produccion fue `asyncpg.InsufficientResourcesError`
# (cuota de computo de Neon agotada), que tambien puede propagarse sin envolver.
_ASYNCPG_UNAVAILABLE: tuple = ()
try:  # pragma: no cover - depende del driver instalado
    from asyncpg import exceptions as _apg

    _ASYNCPG_UNAVAILABLE = (
        _apg.InsufficientResourcesError,
        _apg.CannotConnectNowError,
        _apg.TooManyConnectionsError,
        _apg.PostgresConnectionError,
    )
except Exception:  # noqa: BLE001 - el driver es opcional en tests
    _ASYNCPG_UNAVAILABLE = ()

DB_UNAVAILABLE_ERRORS = (
    OperationalError,
    InterfaceError,
    DBAPIError,
    SQLTimeoutError,
    OSError,  # ConnectionRefusedError, timeouts de socket, DNS
) + _ASYNCPG_UNAVAILABLE


async def _database_unavailable_handler(request: Request, exc: Exception) -> JSONResponse:
    return JSONResponse(
        status_code=503,
        content={"detail": _DB_DOWN_DETAIL, "error": "database_unavailable"},
        headers={"Retry-After": _RETRY_AFTER},
    )


# Se registra recorriendo la tupla, no con decoradores sueltos: con decoradores
# se olvidaron las de asyncpg y `/api/documents` siguio devolviendo 500 en
# produccion mientras home, health y sitemap ya degradaban bien — esos tres
# tienen su propio try/except y por eso tapaban el agujero.
for _exc_cls in DB_UNAVAILABLE_ERRORS:
    app.add_exception_handler(_exc_cls, _database_unavailable_handler)


