@app.get("/health", tags=["meta"])
async def healthcheck() -> Response:
    """Comprueba la base. Antes devolvia siempre "ok" sin tocarla, asi que
    informaba salud mientras la home daba 500 por cuota agotada."""
    try:
        await Database(settings).ping()
    except DB_UNAVAILABLE_ERRORS:
        return JSONResponse(
            status_code=503,
            content={"status": "degraded", "service": "scrapekit-colombia", "database": "unavailable"},
            headers={"Retry-After": _RETRY_AFTER},
        )
    return JSONResponse(
        status_code=200,
        content={"status": "ok", "service": "scrapekit-colombia", "database": "ok"},
    )




