@app.get("/", response_class=HTMLResponse, tags=["ui"])
async def homepage(request: Request) -> HTMLResponse:
    db = Database(settings)
    sources = list_adapters()
    try:
        documents = await db.list_documents(limit=50)
    except DB_UNAVAILABLE_ERRORS:
        # La pagina se sirve igual, con el aviso puesto y 503 para que el
        # rastreador no interprete el catalogo vacio como definitivo.
        html = _render("index.html", documents=[], sources=sources, db_unavailable=True)
        return HTMLResponse(html, status_code=503, headers={"Retry-After": _RETRY_AFTER})
    html = _render("index.html", documents=documents, sources=sources, db_unavailable=False)
    return HTMLResponse(html)


@app.get("/document/{document_id}", response_class=HTMLResponse, tags=["ui"])
async def document_detail(document_id: str, request: Request) -> HTMLResponse:
    db = Database(settings)
    doc = await db.get_document(document_id)
    if doc is None:
        raise HTTPException(status_code=404, detail="Documento no encontrado")
    html = _render("detail.html", document=doc)
    return HTMLResponse(html)


