# ---------------------------------------------------------------------------
# SEO: sitemap.xml
# ---------------------------------------------------------------------------
_SITEMAP_HEADER = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'
_SITEMAP_FOOTER = "</urlset>\n"


@app.get("/sitemap.xml", include_in_schema=False)
async def sitemap_xml() -> Response:
    db = Database(settings)
    # Usar método optimizado que NO carga plain_text para evitar OOM
    try:
        documents = await db.list_documents_for_sitemap(limit=1000)
    except DB_UNAVAILABLE_ERRORS:
        # Un sitemap con solo la raiz es valido; un 503 aqui hace que el
        # rastreador descarte el sitemap entero.
        documents = []

    entries = [
        "  <url>\n"
        "    <loc>https://nomos.stevenvallejo.com/</loc>\n"
        "    <changefreq>daily</changefreq>\n"
        "    <priority>1.0</priority>\n"
        "  </url>\n"
    ]

    for doc in documents:
        # Null-check: saltar documentos sin processed_at
        if doc.processed_at is None:
            continue

        lastmod = doc.processed_at.strftime("%Y-%m-%d")
        entries.append(
            f"  <url>\n"
            f"    <loc>https://nomos.stevenvallejo.com/document/{doc.document_id}</loc>\n"
            f"    <lastmod>{lastmod}</lastmod>\n"
            f"    <changefreq>monthly</changefreq>\n"
            f"    <priority>0.7</priority>\n"
            f"  </url>\n"
        )

    content = _SITEMAP_HEADER + "".join(entries) + _SITEMAP_FOOTER
    return Response(content=content, media_type="application/xml")


